List<List<LatLng>> _parse(List<String> raw) => [
  for (final poly in raw)
    [
      for (final p in poly.split(';'))
        LatLng(double.parse(p.split(',')[0]), double.parse(p.split(',')[1])),
    ],
];

/// Indonesia's landmass pieces.
final List<List<LatLng>> kBasemapIndonesia = _parse(_indonesiaRaw);

/// Neighbouring countries, drawn lighter for context.
final List<List<LatLng>> kBasemapNeighbors = _parse(_neighborsRaw);
